class Solution {
    func modifyFactorize(_ n: Int) -> [Int] {
        var n = n
        var factors: [Int] = []
        var i = 2

        while i <= n {
            while n % i == 0 {
                factors.append(i)
                n /= i
            }
            i += 1
        }

        let sum = factors.reduce(0, +)
        factors.append(sum)
        factors.sort()

        return factors
    }
}
